'use client';
import {TelegramNotifications} from './telegram-notifications';
import {useState,type ReactNode} from 'react';
import Link from 'next/link';
import {ArrowRight,ArrowUpRight,Wallet,ShoppingBag,Store,Clock,Plus,Plug,ShieldCheck,CheckCircle2,RefreshCw,Package,LogOut} from 'lucide-react';
import {api,send,money,date,total,status} from '@/lib/client';
import {mmk,type Pricing,type ShopProduct} from '@/lib/shop-catalog';
import type {Page,Purchase,Shop,Transaction} from '@/lib/types';
import type {OrderRow} from '@/reference-ui/shared/services/financePanelApi';
import {useData,usePanel} from './context';
import {Button,Badge,Empty,Loading,ErrorBox,Pager,Modal,Form,Field,val,SearchBox,Export,Stat,SectionHead,Detail} from './ui';
export function PageTitle({title,sub,action}:{title:string;sub?:string;action?:ReactNode}){return <div className="page-title"><div><span className="eyebrow">SHOP WORKSPACE</span><h1>{title}</h1>{sub&&<p>{sub}</p>}</div>{action}</div>;}
export function Overview(){
 const {profile,invalidate}=usePanel();
 const {data:products,error:productError}=useData('shop-products',()=>api<ShopProduct[]>('products'));
 const {data:pricing,error:priceError}=useData('shop-pricing',()=>api<Pricing>('pricing'));
 const {data,error}=useData('overview-customer-orders',()=>api<Page<OrderRow>>('customer-orders?page=0&size=6'));
 const packages=products?.flatMap(p=>p.packages)||[],active=products?.filter(p=>p.active!==false).length||0,unpriced=packages.filter(p=>!p.priceConfigured).length;
 return <><PageTitle title={`${profile.shop.name} dashboard`} sub="Manage your products, packages and MMK selling prices." action={<Link href="/products" className="btn primary"><Plus size={16}/>Add product</Link>}/>
 <div className="stats-grid"><Stat label="Shop products" value={products?.length??'—'} sub={`${active} active products`} icon={<Store size={18}/>}/><Stat label="Shop packages" value={products?packages.length:'—'} sub={`${packages.filter(p=>p.active!==false).length} active packages`} icon={<Package size={18}/>}/><Stat label="Owner balance" value={`$${money(profile.balance)}`} sub="USD · Main purchasing balance" icon={<Wallet size={18}/>}/><Stat label="Selling rate" value={pricing?.usdMmkRate?mmk(pricing.usdMmkRate):'Not set'} sub="MMK per USD · your shop rate" icon={<ArrowUpRight size={18}/>}/><Stat label="Orders" value={data?.totalElements??'—'} sub="Shop product order history" icon={<ShoppingBag size={18}/>}/><Stat label="Discounted packages" value={products?packages.filter(p=>p.discountPercent>0).length:'—'} sub="Offers in your shop catalog" icon={<Package size={18}/>}/></div>
 {(productError||priceError)&&<ErrorBox message={productError||priceError} retry={invalidate}/>}
 <div className="dashboard-grid"><section className="card"><SectionHead title="Catalog status" sub="Your shop’s customer-facing product settings" action={<Link href="/products" className="text-link">Manage products<ArrowRight size={14}/></Link>}/>{!products?<Loading/>:!products.length?<Empty title="Set up your shop catalog" text="Choose a Main product, select packages and set your own images and MMK prices."/>:<div className="shop-readiness"><div><span>Active products</span><b>{active} / {products.length}</b></div><div><span>Packages with an MMK price</span><b>{packages.length-unpriced} / {packages.length}</b></div><div><span>Discounted packages</span><b>{packages.filter(p=>p.discountPercent>0).length}</b></div><div><span>Product images set</span><b>{products.filter(p=>p.image).length} / {products.length}</b></div></div>}{!!unpriced&&<div className="notice">{unpriced} packages need an MMK price. Set your shop rate or enter manual prices.</div>}<div className="row-actions"><Link href="/product-groups" className="btn">Package Groups</Link><Link href="/pricing" className="btn">Pricing settings</Link></div></section><section className="card wallet-card"><div className="stat-top"><span className="eyebrow">OWNER WALLET</span><Wallet size={22}/></div><strong>${money(profile.balance)}</strong><span className="muted-text">Available balance · USD</span><p>Catalog setup does not charge this balance. Product selling prices are managed separately in MMK.</p><Link href="/transactions" className="text-link">View transactions<ArrowRight size={15}/></Link></section></div>
 <section className="card"><SectionHead title="Recent orders" sub="Shop product orders · MMK" action={<Link href="/product-order" className="text-link">All orders<ArrowRight size={14}/></Link>}/>{error?<ErrorBox message={error} retry={invalidate}/>:!data?<Loading/>:!data.content.length?<Empty title="No orders yet" text="Shop order records will appear here."/>:<div className="table-wrap"><table><thead><tr><th>Order / Product</th><th>Total · MMK</th><th>Status</th></tr></thead><tbody>{data.content.slice(0,6).map(o=><tr key={o.id}><td><Link className="text-button" href="/product-order">{o.publicOrderId||`#${o.id}`} · {o.gameName}</Link><small>{o.packageName} · {date(o.createdAt)}</small></td><td className="numeric">{money(o.sellPrice)} MMK</td><td><Badge value={o.status==='SUCCESS'?'COMPLETED':o.status}/></td></tr>)}</tbody></table></div>}</section></>;
}
export function Transactions(){
 const {profile,invalidate}=usePanel(),[page,setPage]=useState(0),[query,setQuery]=useState('');const {data,error,loading}=useData(`transactions/${page}`,()=>api<Page<Transaction>>(`transactions?page=${page}&size=30`));
 const rows=(data?.content||[]).filter(t=>`${t.publicReference||t.id} ${t.remark} ${t.type} ${t.purchaseId||''}`.toLowerCase().includes(query.toLowerCase()));
 return <><PageTitle title="Transactions" sub={`Balance movements recorded for ${profile.shop.name}.`} action={<Export name={`${profile.shop.code}-transactions.csv`} rows={rows.map(t=>({reference:t.publicReference||t.id,order:t.purchaseId,type:t.type,amount:t.amount,before:t.beforeBalance,after:t.afterBalance,remark:t.remark,date:t.date,time:t.time}))}/>}/><div className="notice"><Wallet size={18}/><p>Your owner balance is <b>${money(profile.balance)} USD</b>. Owner funding and this shop’s purchase/refund records appear below.</p></div><section className="card"><div className="toolbar"><SearchBox value={query} onChange={setQuery} placeholder="Search this page by reference or remark…"/></div>{error?<ErrorBox message={error} retry={invalidate}/>:!data&&loading?<Loading/>:!rows.length?<Empty title="No transactions found"/>:<div className="table-wrap"><table><thead><tr><th>Reference</th><th>Type / Remark</th><th>Change · USD</th><th>Before · USD</th><th>After · USD</th><th>Recorded</th></tr></thead><tbody>{rows.map(t=>{const delta=Number(t.afterBalance)-Number(t.beforeBalance);return <tr key={t.id}><td className="mono">#{t.publicReference||t.id}{t.purchaseId&&<small>Purchase #{t.purchaseId}</small>}</td><td><b>{t.type.replaceAll('_',' ')}</b><small className="wrap-text">{t.remark}</small></td><td className={`numeric ${delta>=0?'positive':'negative'}`}>{delta>=0?'+':'−'}{money(Math.abs(delta))}</td><td className="numeric">{money(t.beforeBalance)}</td><td className="numeric">{money(t.afterBalance)}</td><td className="muted-text">{date(`${t.date}T${t.time}`)}</td></tr>;})}</tbody></table></div>}{data&&<><div className="table-note">Search applies to the current page.</div><Pager page={page} totalPages={data.totalPages} total={data.totalElements} onChange={setPage}/></>}</section></>;
}
export function Connection(){
 const [state,setState]=useState<{state:string;message:string}|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState('');
 async function check(){setBusy(true);setError('');try{const r=await fetch('/api/connection',{cache:'no-store'});if(!r.ok)throw Error('Unable to check the connection.');setState(await r.json());}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 return <><PageTitle title="Service status" sub="Connection between your shop and the Shop Backend." action={<Button disabled={busy} onClick={()=>void check()}><RefreshCw size={15} className={busy?'spin':''}/>{busy?'Checking…':'Check connection'}</Button>}/>{error&&<ErrorBox message={error}/>}<section className="integration-intro card"><span className="shop-icon"><Plug size={25}/></span><div><span className="eyebrow">SHOP ADMIN</span><h2>{state?.state==='connected'?'Your shop is connected':'Check your shop connection'}</h2><p>{state?.message||'Check the connection to see whether the running backends support groups and shop products.'}</p></div></section><div className="notice"><ShieldCheck size={19}/><p>All shops use this admin site. Access and data are scoped to the shop you sign in to.</p></div></>;
}
export function Account(){const {profile,logout}=usePanel();return <><PageTitle title="Your account" sub="Your shop owner account."/><div className="settings-grid"><section className="card"><SectionHead title="Owner profile"/><div className="profile-cover"><span className="avatar large">{profile.userName.slice(0,2).toUpperCase()}</span><h2>{profile.userName}</h2><Badge value="Shop owner"/></div><dl className="details-grid"><Detail label="Owner ID">#{profile.id}</Detail><Detail label="Email">{profile.email}</Detail><Detail label="Status"><Badge value={profile.enabled}/></Detail><Detail label="Created">{date(profile.createdAt)}</Detail></dl></section><div className="stack"><TelegramNotifications/><section className="card"><SectionHead title="Shop workspace"/><dl className="details-grid"><Detail label="Shop">{profile.shop.name}</Detail><Detail label="Shop code">{profile.shop.code}</Detail><Detail label="Shop ID">#{profile.shop.id}</Detail><Detail label="Owner balance">${money(profile.balance)} USD</Detail></dl><p className="card-footnote">This admin workspace displays data for your signed-in shop only.</p></section><section className="card"><SectionHead title="Sign-in security"/><p className="muted-text">Contact Head Admin if you need to reset your password.</p><div className="form-footer"><Button onClick={()=>void logout()}><LogOut size={15}/>Sign out</Button></div></section></div></div></>;}
